@GuardedBy("mService")
protected boolean collectReachableProcessesLocked(ArraySet<ProcessRecord> apps,
        ArrayList<ProcessRecord> processes, ActiveUids uids) {
    final ArrayDeque<ProcessRecord> queue = mTmpQueue;
    queue.clear();
